mapper.update:
UPDATE app_ai_chat_offering SET default_offering = 0, updated_at = CURRENT_TIMESTAMP
WHERE default_offering = 1
AND id != #{excludeId}

mapper.insert:
INSERT INTO app_ai_chat_offering_price (
    offering_id, vip_level, billing_mode, quota_units, diamond_cost, gold_cost, created_at, updated_at
) VALUES (
    #{offeringId}, #{vipLevel}, #{billingMode}, #{quotaUnits}, #{diamondCost}, #{goldCost},
    CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
)

mapper.update:
UPDATE app_h5_user_ai_chat_model SET default_model = 0, updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId} AND default_model = 1
AND id != #{excludeId}

UPDATE app_chat_generation_context
SET charge_status = #{chargeStatus}, consume_biz_ref = #{consumeBizRef}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE app_chat_generation_context
SET updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND charge_status = 'REFUNDING' AND updated_at < #{cutoff}

mapper.select:
SELECT * FROM app_chat_generation_context
WHERE charge_status IN ('RESERVED', 'REFUNDING')
  AND updated_at < #{cutoff}
ORDER BY updated_at ASC, id ASC
LIMIT #{limit}

mapper.delete:
DELETE FROM app_chat_generation_context
WHERE charge_status IN ('FREE', 'COMPLETED', 'REFUNDED')
  AND updated_at < #{cutoff}
ORDER BY id ASC
LIMIT #{limit}
